using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json;
using System.Text.Json.Nodes;
using Jindan.Contracts;
using Jindan.Core;
using Jindan.Infrastructure;

internal static class Program
{
 static string root="",work="";static int pass,fail;static readonly List<object> tests=[];
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static string Hash(string path)=>Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(path)));
 static async Task Test(string name,Func<Task> body){try{await body();pass++;Console.WriteLine("PASS "+name);tests.Add(new{name,passed=true});}catch(Exception e){fail++;Console.WriteLine("FAIL "+name+" "+e.GetType().Name+": "+e.Message);tests.Add(new{name,passed=false,error=e.GetType().Name,message=e.Message});}}
 static async Task Throws(string code,Func<Task> body){try{await body();}catch(WorkspaceException e){Check(e.Code==code,$"Expected{code},got{e.Code}");return;}throw new Exception("Expected "+code);}
 static JsonObject Project(string id="legacy-p")=>new(){["id"]=id,["title"]="합성 이전 프로젝트",["content"]="원래 문장\n둘째 줄",["startDate"]="2026-01-01",["endDate"]="2026-12-31",["ownerUid"]="old-cloud-uid",["password"]="DO_NOT_COPY_LEGACY_CREDENTIAL_66"};
 static JsonObject Process(string id="legacy-process",string project="legacy-p")=>new(){["id"]=id,["title"]="합성 공정",["projectId"]=project,["startDate"]="2026-02-01",["endDate"]="2026-03-01",["isCompleted"]=true};
 static JsonObject TaskRow()=>new(){["id"]="legacy-task",["content"]="원래 할일 제목\n상세 두 번째 줄",["date"]="2026-04-02",["isPublic"]=true,["deleted"]=true};
 static JsonObject Formal(JsonArray? projects=null,JsonArray? processes=null,JsonArray? tasks=null)=>new(){["format"]="jindan-legacy-work/1",["tables"]=new JsonObject{["projects"]=projects??new JsonArray(Project()),["processes"]=processes??new JsonArray(Process()),["tasks"]=tasks??new JsonArray(TaskRow())}};
 static async Task<string> Input(JsonNode value){var path=Path.Combine(work,Guid.NewGuid().ToString("N")+".json");await File.WriteAllTextAsync(path,value.ToJsonString());return path;}
 static void Register(LocalWorkspace store){store.RegisterSchema(new("projects","projects",[new("title","title",Required:true),new("content","content","multiline"),new("startDate","start","date"),new("endDate","end","date")],false));store.RegisterSchema(new("processes","processes",[new("title","title",Required:true),new("content","content","multiline"),new("startDate","start","date"),new("endDate","end","date"),new("isCompleted","done",Choices:["true","false"])]));store.RegisterSchema(new("tasks","tasks",[new("title","title",Required:true),new("content","content","multiline"),new("startDate","date","date"),new("endDate","end","date"),new("isPublic","public",Choices:["true","false"])],false));}
 static async Task<(LocalWorkspace Store,Identity Actor)> Workspace(){var path=Path.Combine(work,"store-"+Guid.NewGuid().ToString("N"));var store=new LocalWorkspace(path);Register(store);var actor=await store.BootstrapAsync("Synthetic legacy owner","synthetic-only-local66!",true);return(store,actor);}
 public static async Task<int> Main(){root=AppContext.BaseDirectory;while(!File.Exists(Path.Combine(root,"Directory.Build.props")))root=Path.GetDirectoryName(root)??throw new Exception("Root missing");work=Path.Combine(root,"artifacts","legacy-import-tests",DateTime.UtcNow.ToString("yyyyMMddTHHmmss")+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);
 await Test("legacy preview preserves original and omits users/passwords/roles from canonical copy",async()=>{var(s,a)=await Workspace();using(s){var input=Formal();input["users"]=new JsonArray(new JsonObject{["password"]="DO_NOT_COPY_LEGACY_CREDENTIAL_66",["role"]="admin"});var source=await Input(input);var before=Hash(source);var state=Hash(Path.Combine(s.DataRoot,"workspace.json"));var p=await s.PreviewLegacyImportAsync(a,source);Check(p.Records==3&&p.OriginalSourcePath==source&&p.OriginalSourceSha256==before&&Hash(source)==before&&Hash(Path.Combine(s.DataRoot,"workspace.json"))==state,"Preview mutated original/store or missed binding");using var zip=ZipFile.OpenRead(p.SourcePath);Check(zip.Entries.Count==1&&zip.Entries[0].FullName=="data.json","Canonical preview has unexpected entries");using var reader=new StreamReader(zip.Entries[0].Open());var json=await reader.ReadToEndAsync();Check(!json.Contains("DO_NOT_COPY_LEGACY_CREDENTIAL_66")&&!json.Contains("old-cloud-uid")&&!json.Contains("PasswordHash"),"Legacy credential/identity data leaked into package");Check(p.Warnings.Any(w=>w.Contains("identity")),"Omission warning absent");}});
 await Test("confirmed new copies remap project links and preserve text/date/deleted flags then rollback",async()=>{var(s,a)=await Workspace();using(s){var source=await Input(Formal());var original=Hash(source);var preview=await s.PreviewLegacyImportAsync(a,source);await Throws("CONFIRMATION",()=>s.ImportAsync(a,preview,false));await s.ImportAsync(a,preview,true);var p=(await s.ListAsync(a,new RecordQuery("projects",IncludeDeleted:true))).Single();var process=(await s.ListAsync(a,new RecordQuery("processes",IncludeDeleted:true))).Single();var task=(await s.ListAsync(a,new RecordQuery("tasks",IncludeDeleted:true))).Single();Check(p.Id!="legacy-p"&&process.Id!="legacy-process"&&process.ProjectId==p.Id&&p.OwnerId==a.Id&&task.OwnerId==a.Id,"IDs/project links/owners not remapped");Check(p.Fields["content"]=="원래 문장\n둘째 줄"&&process.Fields["isCompleted"]=="true"&&task.Fields["content"]=="원래 할일 제목\n상세 두 번째 줄"&&task.Fields["startDate"]=="2026-04-02"&&task.Deleted,"Mapped source data changed");Check((await s.ListAsync(a,new RecordQuery("tasks"))).Count==0&&(await s.ListAsync(a)).Count==1,"Historical tasks revived or legacy users imported");await s.RollbackLastImportAsync(a,true);Check((await s.ListAsync(a,new RecordQuery("projects",IncludeDeleted:true))).Count==0&&Hash(source)==original,"Rollback changed original/source rows");}});
 await Test("exact localStorage serialized arrays and Korean table names are accepted",async()=>{var(s,a)=await Workspace();using(s){var input=new JsonObject{["jindan_db_프로젝트관리"]=new JsonArray(Project()).ToJsonString(),["공정관리"]=new JsonArray(Process()),["jindan_db_할일관리"]=new JsonArray(TaskRow()).ToJsonString(),["jindan_db_회원관리"]="[{\"password\":\"DO_NOT_COPY_LEGACY_CREDENTIAL_66\"}]",["jindan_sync_queue"]="[{\"operation\":\"delete\"}]"};var p=await s.PreviewLegacyImportAsync(a,await Input(input));Check(p.Records==3&&p.Warnings.Any(w=>w.Contains("Ignored")),"Known storage map was not handled explicitly");}});
 await Test("stale original JSON blocks confirmation and remains user-modified",async()=>{var(s,a)=await Workspace();using(s){var source=await Input(Formal());var p=await s.PreviewLegacyImportAsync(a,source);await File.AppendAllTextAsync(source," ");var changed=Hash(source);var state=Hash(Path.Combine(s.DataRoot,"workspace.json"));await Throws("STALE_PREVIEW",()=>s.ImportAsync(a,p,true));Check(Hash(source)==changed&&Hash(Path.Combine(s.DataRoot,"workspace.json"))==state,"Stale rejection changed source or store");}});
 await Test("unsafe/duplicate record IDs and ambiguous table aliases fail",async()=>{var(s,a)=await Workspace();using(s){await Throws("IMPORT_ID",()=>s.PreviewLegacyImportAsync(a,Input(Formal(new JsonArray(Project("../escape")),new JsonArray(),new JsonArray())).GetAwaiter().GetResult()));var duplicate=Formal(new JsonArray(Project(),Project()));await Throws("IMPORT_DUPLICATE",()=>s.PreviewLegacyImportAsync(a,awaitPath(duplicate)));var aliases=new JsonObject{["프로젝트관리"]=new JsonArray(Project()),["jindan_db_프로젝트관리"]=new JsonArray()};await Throws("IMPORT_DUPLICATE",()=>s.PreviewLegacyImportAsync(a,awaitPath(aliases)));}});
 await Test("missing parent project and invalid dates reject without partial import",async()=>{var(s,a)=await Workspace();using(s){await Throws("PROJECT_SCOPE",()=>s.PreviewLegacyImportAsync(a,awaitPath(Formal(new JsonArray(),new JsonArray(Process()),new JsonArray()))));var row=Project();row["startDate"]="2026-02-30";await Throws("DATE",()=>s.PreviewLegacyImportAsync(a,awaitPath(Formal(new JsonArray(row),new JsonArray(),new JsonArray()))));Check((await s.ListAsync(a,new RecordQuery("projects"))).Count==0,"Rejected legacy input partly imported");}});
 await Test("documented long project content is retained without truncation",async()=>{var(s,a)=await Workspace();using(s){var row=Project();var content=new string('x',150000)+"\n끝";row["content"]=content;var p=await s.PreviewLegacyImportAsync(a,await Input(Formal(new JsonArray(row),new JsonArray(),new JsonArray())));await s.ImportAsync(a,p,true);Check((await s.ListAsync(a,new RecordQuery("projects"))).Single().Fields["content"]==content,"Long legacy content was truncated");}});
 await Test("unmapped business fields are rejected instead of silently discarded",async()=>{var(s,a)=await Workspace();using(s){var row=Project();row["undocumentedBusinessNotes"]="Must not disappear";await Throws("LEGACY_UNMAPPED_FIELD",()=>s.PreviewLegacyImportAsync(a,awaitPath(Formal(new JsonArray(row),new JsonArray(),new JsonArray()))));}});
 await Test("malformed/duplicate JSON properties and arbitrary unrelated arrays are rejected",async()=>{var(s,a)=await Workspace();using(s){var path=Path.Combine(work,Guid.NewGuid()+".json");await File.WriteAllTextAsync(path,"{\"프로젝트관리\":[],\"프로젝트관리\":[]}");await Throws("IMPORT_DUPLICATE",()=>s.PreviewLegacyImportAsync(a,path));await Throws("LEGACY_FORMAT",()=>s.PreviewLegacyImportAsync(a,awaitPath(new JsonObject{["arbitraryRows"]=new JsonArray(Project())})));}});
 await Test("viewer or forged admin cannot read legacy preview through service",async()=>{var(s,a)=await Workspace();using(s){var source=await Input(Formal());await s.SaveUserAsync(a,null,"synthetic-viewer","viewer",[],false,"synthetic-viewer-only66");var viewer=await s.LoginAsync("synthetic-viewer","synthetic-viewer-only66");await Throws("FORBIDDEN",()=>s.PreviewLegacyImportAsync(viewer,source));await Throws("UNAUTHENTICATED",()=>s.PreviewLegacyImportAsync(new(a.Id,a.DisplayName,"admin",[]),source));}});
 await Test("canonical candidate tampering blocks apply while original stays intact",async()=>{var(s,a)=await Workspace();using(s){var source=await Input(Formal());var before=Hash(source);var preview=await s.PreviewLegacyImportAsync(a,source);await File.AppendAllTextAsync(preview.SourcePath,"tampered");await Throws("STALE_PREVIEW",()=>s.ImportAsync(a,preview,true));Check(Hash(source)==before&&(await s.ListAsync(a,new RecordQuery("projects"))).Count==0,"Tampered preview mutated original/data");}});
 await File.WriteAllTextAsync(Path.Combine(work,"RESULT.json"),JsonSerializer.Serialize(new{pass,fail,work,syntheticOnly=true,originalWorkspaceReadOnly=true,reportReady=false,supervisorAccepted=false,tests},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"LEGACY_IMPORT_TESTS pass={pass} fail={fail} evidence={work}");return fail==0?0:1;
 }
 static string awaitPath(JsonNode node)=>Input(node).GetAwaiter().GetResult();
}

